/**
 * Starts the Release Relay pipeline (GitHub, GitLab, Bitbucket or Azure DevOps) for one release.
 *   raise  open the pull request (org changes or an existing branch), then scan and validate
 *   check  scan and validate the pull request again
 *   merge  merge the approved pull request, then deploy it to the target org
 *
 * An action (raise, approve, re-run) saves the release with Pending_Run__c set. Callouts can't
 * follow DML in one transaction, so the page then calls start() in a second, short call; the
 * status sync starts any run still pending (for example when the page was closed). No Queueable.
 */
public with sharing class RlyPipeline {

    public static final String RAISE_MODE = 'raise';
    public static final String CHECK_MODE = 'check';
    public static final String MERGE_MODE = 'merge';
    public static final Set<String> MODES = new Set<String>{ RAISE_MODE, CHECK_MODE, MERGE_MODE };

    /** The run each mode may start from; anything else means it was already started or replaced. */
    private static final Map<String, Set<String>> START_FROM = new Map<String, Set<String>>{
        RAISE_MODE => new Set<String>{ 'Submitted' },
        CHECK_MODE => new Set<String>{ 'PR open' },
        MERGE_MODE => new Set<String>{ 'Approved' }
    };

    /** Starts the release's pending run, if any. Returns the release as saved. */
    public static RLY_Release__c start(Id requestId) {
        Data data = new Data();
        RLY_Release__c req = data.request(requestId);
        if (startPending(req)) {
            data.save(req);
        }
        return req;
    }

    /** Starts the pending run on this record (callout only; the caller saves). True when it changed. */
    public static Boolean startPending(RLY_Release__c req) {
        String runMode = req.Pending_Run__c;
        if (String.isBlank(runMode) || !MODES.contains(runMode)) {
            return false;
        }
        req.Pending_Run__c = null;
        if (!START_FROM.get(runMode).contains(req.Status__c)) {
            return true;
        }
        List<String> components = new List<String>();
        List<String> deletions = new List<String>();
        if (runMode == RAISE_MODE) {
            for (RLY_Release_Item__c item : new Data().items(req.Id)) {
                String entry = item.Metadata_Type__c + ':' + item.Component_Name__c;
                if (item.Change_Type__c == 'Deleted') {
                    deletions.add(entry);
                } else {
                    components.add(entry);
                }
            }
        }
        try {
            RlySettings.Connection c = RlySettings.connection(req.Connection__c);
            String workflowMode = runMode == RAISE_MODE ? (req.Mode__c == 'Existing branch' ? 'branch' : 'org') : runMode;
            Map<String, String> inputs = new Map<String, String>{
                'request_id' => req.Name,
                'mode' => workflowMode,
                // A sync back to the source org raises and merges from the org the changes came from.
                'environment' => String.isNotBlank(req.Source_Environment__c) ? req.Source_Environment__c : c.environment,
                'target_environment' => req.Target_Environment__c == null ? '' : req.Target_Environment__c,
                'branch' => req.Source_Branch__c,
                'target' => req.Target_Branch__c,
                'title' => req.Title__c,
                'components' => String.join(components, ','),
                'deletions' => String.join(deletions, ',')
            };
            RlyGitProvider git = RlyGitProvider.forConnection(c);
            RlyGitProvider.Started started;
            if (c.connectionType == RlySettings.GITHUB) {
                try {
                    Map<String, String> withOptions = inputs.clone();
                    withOptions.put('options', options(c));
                    started = git.startPipeline(withOptions);
                } catch (Exception e) {
                    // Workflows from before the options input refuse it: start without them.
                    if (!e.getMessage().containsIgnoreCase('Unexpected input')) {
                        throw e;
                    }
                    started = git.startPipeline(inputs);
                }
            } else {
                started = git.startPipeline(inputs);
            }
            // Providers that return the run are followed by its id; GitHub runs are found by name.
            req.Run_ID__c = started.runId;
            if (started.url != null) {
                req.Run_URL__c = started.url;
            }
            if (runMode == RAISE_MODE) {
                req.Status__c = 'Workflow running';
            } else if (runMode == MERGE_MODE) {
                req.Status__c = 'Merging';
            }
            req.Error_Message__c = null;
        } catch (Exception e) {
            if (runMode == MERGE_MODE) {
                // Keep the approval; the approver can try again once the problem is fixed.
                req.Status__c = 'Ready for approval';
                req.Approval_Status__c = 'Pending';
            } else if (runMode == RAISE_MODE) {
                req.Status__c = 'Failed';
            } else {
                if (req.Scan_Status__c == 'Pending') { req.Scan_Status__c = 'Error'; }
                req.Validation_Status__c = String.isBlank(req.Target_Environment__c) ? 'Not configured' : 'Error';
                req.Status__c = 'Checks failed';
            }
            req.Error_Message__c = ('Could not start the workflow: ' + e.getMessage()).left(2000);
        }
        req.Last_Synced__c = Datetime.now();
        return true;
    }

    /**
     * Workflow options, as JSON:
     *   "scan": "off"     skip the code scan (set on the connection)
     *   "notify": "<env>" when the run ends, tell this org (signing in with that environment) to read the results
     */
    @TestVisible
    private static String options(RlySettings.Connection c) {
        Map<String, String> opts = new Map<String, String>();
        if (c.codeScan == false) {
            opts.put('scan', 'off');
        }
        if (String.isNotBlank(c.environment)) {
            opts.put('notify', c.environment);
        }
        return JSON.serialize(opts);
    }

    /** Releases are read-only to users: the status write-back is elevated, after the action's own checks. */
    private without sharing class Data {
        public RLY_Release__c request(Id reqId) {
            return [SELECT Id, Name, Title__c, Mode__c, Connection__c, Source_Branch__c, Target_Branch__c, Pending_Run__c,
                           Target_Environment__c, Source_Environment__c, Status__c, Approval_Status__c, Scan_Status__c,
                           Validation_Status__c, Run_ID__c, Run_URL__c, Error_Message__c, Last_Synced__c
                    FROM RLY_Release__c WHERE Id = :reqId];
        }
        public List<RLY_Release_Item__c> items(Id reqId) {
            return [SELECT Metadata_Type__c, Component_Name__c, Change_Type__c
                    FROM RLY_Release_Item__c WHERE Release__c = :reqId ORDER BY Name];
        }
        public void save(RLY_Release__c req) {
            update new RLY_Release__c(
                Id = req.Id, Pending_Run__c = req.Pending_Run__c, Status__c = req.Status__c, Run_ID__c = req.Run_ID__c,
                Run_URL__c = req.Run_URL__c, Error_Message__c = req.Error_Message__c, Approval_Status__c = req.Approval_Status__c,
                Scan_Status__c = req.Scan_Status__c, Validation_Status__c = req.Validation_Status__c, Last_Synced__c = req.Last_Synced__c);
        }
    }
}
